SYNTH = {
    "ledgers/LX1/mutants/r17n01_lab3_blank_gbp_cell_read_as_zero.py":
        f"synthetic blank GBP cell 2010-06 (ValueError from the mutant; {scripts}/out/synth_kill_r21.out, case blank_cell)",
    "ledgers/LX1/mutants/lx1c_r18n05_lab3_blank_cell_carried_forward_as_flat_rate.py":
        f"synthetic blank GBP cell 2010-06 (mutant exits 0 with a flat rate; {scripts}/out/synth_kill_r21.out, case blank_cell)",
    "ledgers/LX1/mutants/lx1c_r18n03_lab3_zero_change_tested_after_rounding_to_four_places.py":
        f"synthetic 1e-5 relative move at month index 100 (zero count differs; {scripts}/out/synth_kill_r21.out, case tiny_move)",
    "ledgers/LX1/mutants/lx1c_r18n04_lab3_window_two_centred_on_window_one_mean.py":
        f"synthetic window-two drift of 1 percent a month (sd differs; {scripts}/out/synth_kill_r21.out, case drift)",
    "ledgers/LX1/mutants/lx1c_r18n02_lab3_difference_of_printed_sds.py":
        f"synthetic window-two changes scaled by 0.5 (printed-sd difference 1.14 against 1.13; {scripts}/out/diff_printed_search_r21.out)",
    "ledgers/LX1/mutants/lx1c_r20n04_lab3_zero_test_with_tolerance.py":
        f"synthetic 1e-10 relative move (zero count 668 against 667; {scripts}/out/tiny_move_1e10_r21.out); a 1e-5 move is not counted (synth_kill_r21.out)",
}

kill_rows = {r[0]: r for r in json.loads((root / scripts / "kill_all_r21.json").read_text())}
mutants = []
for f in sorted((root / "ledgers/LX1/mutants").glob("*.py")):
    rel = f"ledgers/LX1/mutants/{f.name}"
    first = next(line for line in f.read_text(encoding="utf-8").splitlines() if line.strip())
    desc = re.sub(r'^(#\s*|"""\s*)', "", first.strip()).strip()
    desc = desc.replace('"""', "").strip()
    lab = kill_rows[f.name][1]
    if rel in SYNTH:
        killed_by = SYNTH[rel]
    else:
        assert kill_rows[f.name][2] == "KILLED", f.name
        killed_by = f"embedded snapshot: lab-LX1-project-{lab} expected block ({scripts}/out/kill_all_r21.out)"
    mutants.append({"name": f.name, "description": desc[:300], "killed_by": killed_by})

ROW = lambda id_, check, location, status, evidence, fix="": {  # noqa: E731
    "id": id_, "check": check, "location": location, "status": status, "evidence": evidence,
    **({"fix": fix} if status != "PASS" else {}),
}

